const releaseSlotCapacity = `-- name: ReleaseSlotCapacity :execrows
UPDATE scheduling.slot
SET booked = booked - 1, updated_at = $1
WHERE tenant_id = $2 AND slot_id = $3 AND booked > 0
`

type ReleaseSlotCapacityParams struct {
	UpdatedAt pgtype.Timestamptz
	TenantID  uuid.UUID
	SlotID    uuid.UUID
}

// Gives capacity back when an appointment is cancelled.
//
// Guarded on booked > 0 so a double cancellation cannot drive the counter
// negative and hand the clinic capacity it does not have.
func (q *Queries) ReleaseSlotCapacity(ctx context.Context, arg ReleaseSlotCapacityParams) (int64, error) {
	result, err := q.db.Exec(ctx, releaseSlotCapacity, arg.UpdatedAt, arg.TenantID, arg.SlotID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const setAppointmentStatus = `-- name: SetAppointmentStatus :execrows
UPDATE scheduling.appointment
SET status = $1, updated_at = $2, version = version + 1
WHERE tenant_id = $3
  AND appointment_id = $4
  AND version = $5
`

type SetAppointmentStatusParams struct {
	Status          string
	UpdatedAt       pgtype.Timestamptz
	TenantID        uuid.UUID
	AppointmentID   uuid.UUID
	ExpectedVersion int64
}

// Optimistic concurrency on version: two clerks checking in the same patient
// at once would otherwise both write, and the second would overwrite a status
// it never saw.
func (q *Queries) SetAppointmentStatus(ctx context.Context, arg SetAppointmentStatusParams) (int64, error) {
	result, err := q.db.Exec(ctx, setAppointmentStatus,
		arg.Status,
		arg.UpdatedAt,
		arg.TenantID,
		arg.AppointmentID,
		arg.ExpectedVersion,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

